"""Write 04_results/summary.md: every headline number, read from saved results.

Run:  python summarize_results.py
"""
import sys
from pathlib import Path

import numpy as np

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "03_code"))
from oldroydb import analytical as an  # noqa: E402
from oldroydb import compare, report as rp  # noqa: E402

ref = compare.load_reference(ROOT / "04_results" / "reference" / "fd_eps0.npz")
fe = rp.load_fe(ROOT)
out = ["# Results summary", "",
       "Generated by `03_code/scripts/summarize_results.py` from the files in `04_results/`.",
       "ΔP is the centreline pressure drop between Z = 0 and Z = 1 (paper's scaling).",
       "\"PINN\" = pressure difference of the network; \"PINN (mom.)\" = integral of the",
       "centreline momentum balance (eq. 5.3). Errors in percent.", ""]


def table(header, rows):
    out.append("| " + " | ".join(header) + " |")
    out.append("|" + "---|" * len(header))
    for r in rows:
        out.append("| " + " | ".join(r) + " |")
    out.append("")


# ---- lubrication limit
runs0 = rp.load_runs(ROOT, 0.0)
out += ["## 1. Lubrication limit (ε → 0): PINN vs our reference solver", ""]
rows = []
for d, (m, h) in runs0.items():
    dp = m.pressure_drop(d)
    r = float(np.interp(d, ref["De"], ref["dP"]))
    s3 = an.pressure_drop(d, 3)
    rows.append([f"{d:.2f}", f"{dp['direct']:.4f}", f"{dp['momentum']:.4f}", f"{r:.4f}",
                 f"{100 * (dp['direct'] / r - 1):+.2f}", f"{100 * (dp['momentum'] / r - 1):+.2f}",
                 f"{100 * (s3 / r - 1):+.1f}"])
table(["De", "PINN", "PINN (mom.)", "reference", "PINN err", "PINN (mom.) err",
       "formula O(De³) err"], rows)

out += ["Field errors (relative L2 over 0 ≤ Z ≤ 1; last column excludes the corner zones):", ""]
rows = [[f"{r[0]:.2f}"] + ["-" if np.isnan(v) else f"{v:.2f}" for v in r[1:]]
        for r in rp.error_table(ref, runs0)]
table(["De", "Uz", "Uy", "Azz", "Ayy", "Ayz", "worst, 0.05 < Z < 0.95"], rows)

# ---- full 2-D against the paper's finite elements
out += ["## 2. Full 2-D: PINN vs the paper's finite-element simulations", ""]
rows = []
for eps in (0.02, 0.1):
    for d, (m, h) in rp.load_runs(ROOT, eps).items():
        dp = m.pressure_drop(d)
        x, y = fe[eps]
        f = float(y[np.argmin(np.abs(x - d))])
        rows.append([f"{eps:g}", f"{d:.2f}", f"{dp['direct']:.4f}", f"{dp['momentum']:.4f}",
                     f"{f:.4f}", f"{100 * (dp['direct'] / f - 1):+.2f}",
                     f"{100 * (dp['momentum'] / f - 1):+.2f}",
                     f"{100 * (an.pressure_drop(d, 3) / f - 1):+.1f}"])
table(["ε", "De", "PINN", "PINN (mom.)", "paper FE", "PINN err", "PINN (mom.) err",
       "formula O(De³) err"], rows)

# ---- reference solver against the paper's finite elements
out += ["## 3. Our reference solver (ε → 0) vs the paper's FE at ε = 0.02", ""]
_, rows3 = rp.reference_vs_fe(ref, fe, 0.02)
table(["De", "reference", "paper FE", "diff"],
      [[f"{r[0]:.3f}", f"{r[1]:.4f}", f"{r[2]:.4f}", f"{r[3]:+.2f}"] for r in rows3])

# ---- training cost
out += ["## 4. Training cost (Apple M4 laptop)", ""]
rows = []
for eps in (0.0, 0.02, 0.1):
    for d, (m, h) in rp.load_runs(ROOT, eps).items():
        dev = "GPU, float32" if m.cfg.device == "mps" else "CPU, float64 polish"
        rows.append([f"{eps:g}", f"{d:.2f}", dev, f"{h['train_seconds'] / 60:.1f}",
                     f"{h['loss'][-1]:.1e}", f"{h['test_loss']:.1e}"])
param = rp.load_param(ROOT, 0.02)
if param is not None:
    h = param[1]
    rows.append(["0.02", "0–0.3 (input)", "CPU, float64 polish", f"{h['train_seconds'] / 60:.1f}",
                 f"{h['loss'][-1]:.1e}", f"{h['test_loss']:.1e}"])
table(["ε", "De", "hardware", "minutes", "final loss", "held-out loss"], rows)

(ROOT / "04_results" / "summary.md").write_text("\n".join(out) + "\n")
print("\n".join(out))
